/* Desktop workflow: reconnect reads only. No output is generated by rendering. */
'use strict';
const $=id=>document.getElementById(id), base='/api/servo-workbench/v1/';
let auth={}, state=null, activePlan=null, selected=null, previousCandidate=null;
let acting=false, motionActive=false, owner=false, lastEvent=0, simIndex=0;
let automaticPreviewKey=null;
const names={right_hip_yaw:'右髋转向',right_hip_roll:'右髋侧摆',right_hip_pitch:'右髋俯仰',right_knee:'右膝',right_ankle:'右踝',left_hip_yaw:'左髋转向',left_hip_roll:'左髋侧摆',left_hip_pitch:'左髋俯仰',left_knee:'左膝',left_ankle:'左踝',neck_pitch:'颈部俯仰',head_pitch:'头部俯仰',head_yaw:'头部转向',head_roll:'头部侧摆',mouth:'嘴部'};
const states={pending:'待配置',configuring:'配置中',readback:'读回通过 · 待掉电复核',verified:'掉电复核通过',interrupted:'中断 · 待核对',repair:'需要修复',rolled_back:'已回退 · 待复核'};
const connections={waiting:'等待回应',stabilizing:'稳定读取中',ready:'已稳定 · 待确认',blocked:'访问已阻断',paused:'已暂停'};
const phases={waiting:'只读等待',confirmation:'待确认',configuring:'正在配置',waiting_next:'等待换下一只',interrupted:'中断待核对',testing:'台架检查中',midpoint:'中位处理中',rolling_back:'参数回退中',verifying_all:'整组复核中',complete:'复核完成',repair:'需要修复'};
const text=(id,value)=>$(id).textContent=value;
function node(tag,value,cls){const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;return e;}
function error(e){text('error',(e.code?e.code+' · ':'')+e.message);$('error').hidden=false;}
function freeze(){activePlan=null;owner=false;motionActive=false;for(const id of ['preview','apply','verify'])$(id).disabled=true;$('planBox').hidden=true;}
async function api(method,body){const settings=body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Workbench-CSRF':auth.csrf},body:JSON.stringify(body)};const r=await fetch(base+method,settings);const value=await r.json();if(!r.ok){const e=new Error(value.error||'请求失败');e.code=value.code;throw e;}return value;}
async function perform(fn){if(acting)return;acting=true;$('error').hidden=true;try{await fn();}catch(e){error(e);}finally{acting=false;motionActive=false;await refresh();}}
function model(){return $('modelConfirmed').checked;}
function readiness(){if(!$('single').checked)throw new Error('请确认当前物理上只有一只舵机且机构固定。');if(!model())throw new Error('请核对实物型号。');}
function render(s){
 owner=!!s.writer_owned; text('agentState',s.agent_state==='reconnecting'?'正在重连':'在线');text('agentNote',s.remote?'SSH · '+s.remote:'电脑本地向导 · 进度持久保存');
 if(!s.id){freeze();text('adapterState',s.demo?'模拟设备':s.connected_read_only?'已绑定 · 只读':'尚未绑定');text('busState','等待建立批次');if(s.remote_authority){text('notice',s.error||'等待板端上线，已有进度保留在板端。');text('adapterState','等待板端');text('busState','状态未知');}else text('notice',s.demo?'先选择套件并建立批次。当前为演练，不访问任何硬件。':'LIVE已就绪，尚未绑定串口。选择XL330及图示预设，刷新端口并只读连接，再建立批次。');if(!state||!s.remote_authority)state=s;return;}
 state=s;text('modeBadge',s.simulated?'SIMULATION / 无硬件':'LIVE / '+(s.authority==='board'?'板端执行':'电脑串口'));
 $('simControls').hidden=!s.simulated;$('realConnection').hidden=s.simulated||s.authority==='board';
 text('adapterState',({present:'已找到',missing:'未连接',blocked:'被占用 / 已阻断',ambiguous:'需要选择',waiting:'等待'})[s.adapter_state]||s.adapter_state);
 text('busState',connections[s.connection_state]||'等待');text('busNote',s.last_error||'没有回应不等同于确认断电');
 text('count',String(s.configured||0)+'/15');text('persistCount','掉电复核 '+(s.completed||0)+'/15');text('phase',phases[s.phase]||s.phase);
 text('notice',s.last_message||(s.connection_state==='ready'?'已读取设备。请核对实物标签，再预览本次差异。':'进度已保存，等待连接与供电恢复；不会自动写入。'));
 if(s.connection_state==='ready'&&!s.running_job&&!s.slots.some(x=>x.id===s.observed?.id&&['readback','verified'].includes(x.state)))text('notice','已发现下一只候选。请核对实物标签与配置差异，确认后才会写入。');
 const facts=$('batchFacts');facts.replaceChildren();for(const [k,v]of [['批次',s.id.slice(0,12)],['套件',s.kind+' / '+s.layout],['预设',s.version],['修订',s.revision],['连接代次',s.connection_epoch],['权威记录',s.authority]])facts.append(node('dt',k),node('dd',String(v)));
 const list=$('sessions'),old=list.value;list.replaceChildren();for(const row of s.sessions||[]){const o=node('option',row.id.slice(0,8)+' · '+row.kind+' · '+(phases[row.phase]||row.phase));o.value=row.id;list.append(o);}list.value=old||s.id;
 const candidate=s.observed, candidateKey=candidate?candidate.id+':'+candidate.baud+':'+s.connection_epoch:null;
 if(candidateKey!==previousCandidate){selected=null;activePlan=null;previousCandidate=candidateKey;}
 if(selected===null){const known=candidate?s.slots.findIndex(x=>x.id===candidate.id&&['readback','verified'].includes(x.state)):-1;selected=known>=0?known:Math.min(s.cursor,14);}
 const slot=s.slots[selected];text('currentTitle',(names[slot.name]||slot.name)+' · ID'+slot.id);
 if(!$('assetLabel').value||$('assetLabel').dataset.slot!==String(selected)){$('assetLabel').value=slot.label||'DUCK-'+s.id.slice(0,6)+'-ID'+slot.id;$('assetLabel').dataset.slot=String(selected);}
 const obs=$('observed');obs.replaceChildren();
 if(candidate){const m=candidate.metrics;obs.append(node('b','发现 ID'+candidate.id+' · '+candidate.baud+' bps'));const row=node('div','', 'metric-row');for(const [k,v,u]of [['位置',m.position_raw,'刻度'],['电压',m.voltage_v,'V'],['温度',m.temperature_c,'°C'],['电流',m.current_ma,'mA'],['扭矩',m.torque,'']])row.append(node('span',k+' '+(v??'未知')+' '+u));obs.append(row,node('small','身份依据：'+(candidate.identity.basis==='model_register'?'型号寄存器':'实物型号声明与HLS固件读数')+'；不代表唯一实体序列号。'));}else obs.append(node('span','等待稳定读取。舵机与USB断开不会丢失本批次进度。'));
 const slots=$('slots');slots.replaceChildren();s.slots.forEach((x,i)=>{const b=node('button','', 'slot '+x.state+(i===selected?' selected':''));b.type='button';b.dataset.index=String(i);b.append(node('strong','ID '+x.id),node('small',names[x.name]||x.name),node('span',states[x.state]||x.state,'state'));if(x.label)b.append(node('small',x.label));b.onclick=()=>{selected=i;$('assetLabel').dataset.slot='';render(state);};slots.append(b);});
 if(activePlan&&(!s.plan||s.plan.hash!==activePlan.plan.hash)){activePlan=null;}
 $('planBox').hidden=!activePlan;$('preview').disabled=acting||s.connection_state!=='ready'||!!s.running_job;
 $('apply').disabled=acting||!activePlan||s.connection_state!=='ready';$('verify').disabled=acting||s.configured!==15;
 $('setup').open=false;
}
async function refresh(){try{const s=await api('status');render(s);if(s.id){const events=await api('events?after='+lastEvent);for(const e of events){lastEvent=Math.max(lastEvent,e.seq);const p=node('p',new Date(e.at*1000).toLocaleTimeString()+' · '+e.kind+' · '+JSON.stringify(e.details));$('events').prepend(p);}while($('events').children.length>100)$('events').lastChild.remove();}}catch(e){freeze();text('agentState','连接中断');text('notice','向导仍保留当前内容，等待本地服务或板端重连。');}}
const registerNames={7:'ID',8:'Baud Rate',9:'Return Delay',10:'Drive Mode',11:'Operating Mode',20:'Homing Offset',62:'PWM Slope',63:'Shutdown'};
function registerValue(address,value){if(value===undefined)return '未知';if(address===20&&value>=2147483648)return String(value-4294967296);if(address===8&&value===3)return '3（1,000,000 bps）';if(address===63&&value===52)return '52 / 0x34';return String(value);}
function showPlan(result){activePlan=result;const p=result.plan,box=$('planChanges');box.replaceChildren();if(p.changes){const table=document.createElement('table');const head=document.createElement('tr');for(const t of ['参数 / 地址','当前值','计划值','操作'])head.append(node('th',t));table.append(head);const rows=p.desired?Object.entries(p.desired).map(([a,v])=>({address:Number(a),old:p.binding[a],value:v})):p.changes;for(const c of rows){const row=document.createElement('tr');row.append(node('td',(registerNames[c.address]||'寄存器')+' / '+c.address),node('td',registerValue(c.address,c.old)),node('td',registerValue(c.address,c.value)),node('td',c.old===c.value?'已一致 · 不写入':'将写入并读回'));table.append(row);}box.append(table);if(state?.kind==='xl330'&&p.desired)box.append(node('p','Homing Offset沿用原模板：ID13/23=-512，其余=0；本次不做逐颗标定。Shutdown=52取消输入电压故障触发的扭矩关闭；供电仍必须符合3.7–6.0V规格。','muted'));if(!p.changes.length)box.append(node('p','当前读数与预设一致，将只登记核对结果。'));}else box.append(node('p',p.effect||JSON.stringify(p.test)));text('apply',({midpoint:'明确确认：把当前位置定义为硬件中位',motion:'明确确认：开始独立单舵机台架检查',rollback:'明确确认：恢复本配置任务的备份值'})[p.kind]||'确认本只配置');$('planBox').hidden=false;$('apply').disabled=false;$('planBox').scrollIntoView({behavior:'smooth',block:'nearest'});}
function useImagePreset(){$('kind').value='xl330';$('layout').value='microduck';$('version').value='0.18.3';$('shutdown52').checked=true;text('notice','已选择图示XL330预设。先选适配器并只读连接，再建立批次；此操作没有连接或写入舵机。');}
$('imagePreset').onclick=useImagePreset;
if(new URLSearchParams(location.search).get('preset')==='xl330-image')useImagePreset();

async function preview(kind){readiness();if(kind&&!$('benchReady').checked)throw new Error('可选维护需要另外确认独立台架及可立即断电条件。');const r=await api(kind?'action-plan':'plan',kind?{kind,model_confirmed:model(),standalone:true,operator_ready:true}:{index:selected,label:$('assetLabel').value,model_confirmed:model(),same_servo:$('sameServo').checked});showPlan(r);}
async function automaticPreview(){
 const s=state;
 if(acting||activePlan||!owner||!s?.id||s.connection_state!=='ready'||s.running_job||s.needs_identity||!model()||!$('single').checked||s.slots[selected]?.state!=='pending')return;
 const key=s.id+':'+s.connection_epoch+':'+s.observed?.id+':'+selected;
 if(automaticPreviewKey===key)return;automaticPreviewKey=key;
 await perform(()=>preview());
}
for(const id of ['single','modelConfirmed'])$(id).onchange=automaticPreview;
$('assetLabel').oninput=()=>{activePlan=null;$('planBox').hidden=true;$('apply').disabled=true;};
setInterval(automaticPreview,600);
$('create').onclick=()=>perform(async()=>{const kind=$('kind').value,options={};if(kind==='hd1910'){if($('gains').checked)options.gains=[5,10];if($('protection').checked)options.enable_protection=true;if($('currentChoice').checked)options.protection_current_a=1.5;}else if($('shutdown52').checked)options.shutdown52=true;await api('session-create',{kind,layout:$('layout').value,version:$('version').value,options});owner=true;selected=null;simIndex=0;lastEvent=0;});
$('claim').onclick=()=>perform(async()=>{await api('claim',{});owner=true;});
$('open').onclick=()=>perform(async()=>{await api('session-open',{id:$('sessions').value});selected=null;lastEvent=0;});
$('preview').onclick=()=>perform(()=>preview());
for(const id of ['midpoint','motion','rollback'])$(id).onclick=()=>perform(()=>preview(id));
$('apply').onclick=()=>perform(async()=>{if(!activePlan)throw new Error('请重新预览');const p=activePlan,request={job_id:crypto.randomUUID(),revision:p.revision,connection_epoch:p.plan.connection_epoch,plan_hash:p.plan.hash};motionActive=p.plan.kind==='motion';if(motionActive)await api('heartbeat',{});const job=await api('apply',request);activePlan=null;$('jobResult').hidden=false;$('jobResult').replaceChildren(node('strong','任务 '+job.state),node('p',job.kind==='configuration'?'本次读回已登记；请断电换机。持久性留待整组复核。':'可选操作已记录，请核对实际读数。'));});
$('cancel').onclick=async()=>{motionActive=false;try{await api('cancel',{});text('notice','正在停止后续操作；卸力结果以读回为准。');}catch(e){error(e);}};
for(const id of ['pause','resume','detect'])$(id).onclick=()=>perform(()=>api(id,{}));
$('scan').onclick=()=>perform(async()=>{const r=await api('scan',{});$('checkResult').replaceChildren(node('pre',JSON.stringify(r,null,2)));});
$('reconcile').onclick=()=>perform(async()=>{const r=await api('reconcile',{same_servo:$('sameServo').checked,model_confirmed:model()});$('checkResult').replaceChildren(node('p','中断状态已核对；剩余差异仍需重新预览，不自动重发。'));});
$('checks').onclick=()=>perform(async()=>{const r=await api('checks');const box=$('checkResult');box.replaceChildren(node('p',r.conclusion));for(const f of r.findings){const d=node('div','','finding');d.append(node('strong',f.code+' · '+JSON.stringify(f.raw)),node('p',f.advice),node('small',f.source+' · '+f.verification));box.append(d);}});
$('verify').onclick=()=>perform(async()=>{const r=await api('verify',{power_cycle_confirmed:$('powerConfirmed').checked,model_confirmed:model()});const box=$('verifyResult');box.replaceChildren();for(const row of r.rows)box.append(node('p','ID'+row.id+' · '+(row.ok?'读回一致':row.error)));});
$('export').onclick=()=>perform(async()=>{const report=await api('report'),url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='servo-workbench-'+report.session.id.slice(0,8)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('printLabels').onclick=()=>window.print();
document.querySelectorAll('[data-sim]').forEach(b=>b.onclick=()=>perform(()=>api('simulation',{op:b.dataset.sim})));
$('simNew').onclick=()=>perform(async()=>{await api('simulation',{op:'detach'});await api('detect',{});const label='part-'+Date.now()+'-'+(++simIndex);await api('simulation',{op:'attach',label});selected=null;});
$('refreshPorts').onclick=()=>perform(async()=>{const rows=await api('ports');$('ports').replaceChildren();for(const p of rows){const o=node('option',p.device+' · '+(p.serial_number||'序列号未知'));o.value=JSON.stringify(p);$('ports').append(o);}});
$('connect').onclick=()=>perform(async()=>{if(!$('ports').value)throw new Error('先选择端口');await api('connect',{kind:$('kind').value,selection:JSON.parse($('ports').value)});});
document.addEventListener('visibilitychange',()=>{if(document.hidden){motionActive=false;api('cancel',{}).catch(()=>{});}});
setInterval(()=>{if(motionActive&&!document.hidden)api('heartbeat',{}).catch(()=>{motionActive=false;});},200);
setInterval(()=>{if(owner)api('claim',{}).catch(()=>{owner=false;});},10000);
(async()=>{try{auth=await api('session');const s=await api('status');owner=!!s.writer_owned;text('modeBadge',s.demo?'SIMULATION / 无硬件':'LIVE / 需明确连接');$('simControls').hidden=!s.demo;$('realConnection').hidden=!!s.demo||!!s.remote;$('connectionGuide').textContent=s.remote?'执行端：SSH '+s.remote+'；不自动部署或启停正式服务。':s.demo?'当前为演练。真实电脑直连使用 serve --real；板端使用 serve --ssh 已登记主机。':'请选择物理串口并明确连接；绑定后自动只读检测。';render(s);await refresh();setInterval(refresh,1000);}catch(e){error(e);}})();
